def compact(messages, budget):
    pinned={i for i,m in enumerate(messages) if m['role']=='system'}
    remaining=budget-sum(len(messages[i]['content']) for i in pinned)
    if remaining<0: raise ValueError('budget')
    keep=set(pinned)
    for i in reversed(range(len(messages))):
        if i in pinned: continue
        cost=len(messages[i]['content'])
        if cost>remaining: break
        keep.add(i); remaining-=cost
    return [m for i,m in enumerate(messages) if i in keep]

